import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

class ContactRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            Student(
                "3", "Varrow", "Ines", "B", "ines@x.test"
            ),
            Student(
                "1", "Quillon", "Sefa", "A", "sefa@x.test"
            ),
            Student(
                "2", "Thistle", "Bram", "A", "bram@x.test"
            )
        ]

    def test_rows_sorted_by_name_and_lined_up(self):
        expected = [
            "Quillon, Sefa  A  sefa@x.test",
            "Thistle, Bram  A  bram@x.test",
            "Varrow, Ines   B  ines@x.test"
        ]
        rows = contact_rows(self.students)
        self.assertEqual(rows, expected)

    def test_missing_email_names_the_student(self):
        self.students.append(
            Student("4", "Ortega", "Lu", "B", None)
        )
        with self.assertRaises(ProjectError) as context:
            contact_rows(self.students)
        self.assertIn("Ortega, Lu", str(context.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
